python3 -c "
import os, json, requests

api_key = open(os.environ.get('GALAXY_API_KEY_FILE', '/claude_home/.galaxy/api_key')).read().strip()
url = 'https://usegalaxy.org'
headers = {'x-api-key': api_key, 'Content-Type': 'application/json'}

history_id = 'bbd44e69cb8906b50dccd1d6c81b2bd5'

inputs = {
    'input1': {'src': 'hda', 'id': 'f9cad7b01a4721350540e1b0ecce96a3'},
    'groupcol': '13',
    'ignorecase': 'false',
    'operations': [
        {
            'optype': 'length',
            'opcol': '1',
            'opround': 'no'
        }
    ]
}

payload = {
    'history_id': history_id,
    'tool_id': 'Grouping1',
    'inputs': json.dumps(inputs),
    'input_format': '21.01'
}

r = requests.post(f'{url}/api/tools', headers=headers, json=payload)
print(f'Status: {r.status_code}')
if r.status_code == 200:
    result = r.json()
    print(json.dumps(result, indent=2)[:3000])
    if 'jobs' in result:
        for job in result['jobs']:
            print(f'Job ID: {job[\"id\"]}, state: {job[\"state\"]}')
            # Wait for it
            import time
            for i in range(30):
                time.sleep(2)
                jr = requests.get(f'{url}/api/jobs/{job[\"id\"]}', headers=headers)
                js = jr.json()
                if js.get('state') in ('ok', 'error'):
                    print(f'Final state: {js.get(\"state\")}')
                    break
                if i % 5 == 0:
                    print(f'  Waiting... state={js.get(\"state\")}')
    if 'outputs' in result:
        for out in result['outputs']:
            ds_id = out['id']
            r2 = requests.get(f'{url}/api/datasets/{ds_id}/display', headers=headers)
            print(f'Output ({ds_id}):')
            print(repr(r2.text[:500]))
else:
    print(f'Error: {r.text[:500]}')
"

